'use strict';
// Source-backed hot-match fixture and one fresh-process actor sample.
const fs=require('node:fs'),path=require('node:path'),assert=require('node:assert/strict');
const lib=require('./moderation_advanced_source.cjs');
const {realm,sha,root}=lib;
const units=s=>Array.from({length:s.length},(_,i)=>s.charCodeAt(i));
const p=(id,source,boundary='whole_word',ignoreCase=true)=>({id,source,boundary,ignoreCase});
const suites={
 ascii:i=>({text:i%2?'ordinary friendly message':'hello BADWORD! offer now',terms:['badword','scam'],patterns:[p('offer','offer')]}),
 long:i=>({text:('ordinary café 😀 words '.repeat(22)).slice(0,480)+(i%2?' ordinary ending':' !target! ending'),terms:['target','scam'],patterns:[p('target','target'),p('offer','offer','anywhere'),p('digits','[0-9]+','anywhere')]}),
 unicode:i=>({text:['😀 CAFÉ !Σ! \ud800 tail','\udc00 !ς! e\u0301 😀','ordinary 😀 \ud800 end','!café! Σ \udc00'][i%4],terms:['cafe','σ'],patterns:[p('sigma','Σ','anywhere'),p('accent','café','whole_word')]}),
 regex_only:i=>({text:i%2?'nothing to see':'😀 !offer! 123',terms:[],patterns:[p('offer','offer'),p('digits','[0-9]+','anywhere')]}),
 many:i=>({text:i%2?'ordinary message no target':'message !term31! !regex9! end',terms:Array.from({length:32},(_,n)=>`term${n}`),patterns:Array.from({length:10},(_,n)=>p(`r${n}`,`regex${n}`,n%2?'anywhere':'whole_word'))})
};
const names=Object.keys(suites);
function project(m){return {matcherID:units(m.matcherID),text:units(m.text),start:m.start,end:m.end};}
function checksum(results){let h=2166136261;const add=n=>h=Math.imul(h^n,16777619)>>>0;for(const result of results){add(result.length);for(const m of result){for(const x of m.matcherID)add(x);add(65536);for(const x of m.text)add(x);add(65536);add(m.start);add(m.end);}add(65537);}return h;}
function build(){const api=realm({}).api;const workloads={};for(const name of names){const cases=[];for(let i=0;i<32;i++){const c=suites[name](i);assert(c.patterns.length<=10);for(const pat of c.patterns){assert(pat.source.length>0&&pat.source.length<=250);assert(/^[\w-]{1,64}$/.test(pat.id));}const result=api.findBlacklistMatches(c.text,c.terms,c.patterns).map(project);cases.push({text:units(c.text),terms:c.terms.map(units),patterns:c.patterns.map(q=>({id:units(q.id),source:units(q.source),boundary:q.boundary,ignoreCase:q.ignoreCase})),result});}workloads[name]=cases;}return {format:1,workloads};}
function external(dir){assert(path.isAbsolute(dir));const real=fs.realpathSync(dir),workspace=fs.realpathSync(path.join(root,'..'));assert(real!==workspace&&!real.startsWith(workspace+path.sep));return real;}
function expectedBytes(){return JSON.stringify(build(),null,2)+'\n';}
function input(){const file=process.env.DIMA_ADVANCED_BENCHMARK_FIXTURE;assert(file&&path.isAbsolute(file));const real=fs.realpathSync(file);external(path.dirname(real));const bytes=fs.readFileSync(real),hash=sha(bytes);assert(/^[0-9a-f]{64}$/.test(process.env.DIMA_ADVANCED_BENCHMARK_SHA256||''));assert.equal(hash,process.env.DIMA_ADVANCED_BENCHMARK_SHA256);assert.equal(bytes.toString(),expectedBytes());return {data:JSON.parse(bytes),hash};}
function decode(u){return String.fromCharCode(...u);}
function actor(name){assert(names.includes(name));const {data,hash}=input();const expected=data.workloads[name];const pool=expected.map(c=>({text:decode(c.text),terms:c.terms.map(decode),patterns:c.patterns.map(q=>({id:decode(q.id),source:decode(q.source),boundary:q.boundary,ignoreCase:q.ignoreCase}))}));const api=realm({}).api;for(let i=0;i<32;i++)assert.deepEqual(api.findBlacklistMatches(pool[i].text,pool[i].terms,pool[i].patterns).map(project),expected[i].result);
 const rounds=Number(process.env.DIMA_ADVANCED_BENCH_ROUNDS||250);assert(Number.isSafeInteger(rounds)&&rounds>=1&&rounds<=500);const count=rounds*32;
 for(let w=0;w<3;w++){const retained=new Array(count);let n=0;for(let i=0;i<rounds;i++)for(const c of pool)retained[n++]=api.findBlacklistMatches(c.text,c.terms,c.patterns);assert.equal(n,count);}
 assert.equal(typeof global.gc,'function','requires --expose-gc');global.gc();const results=new Array(count);let n=0;const start=process.hrtime.bigint();for(let i=0;i<rounds;i++)for(const c of pool)results[n++]=api.findBlacklistMatches(c.text,c.terms,c.patterns);const elapsed=process.hrtime.bigint()-start;
 const projected=results.map(r=>r.map(project));for(let i=0;i<count;i++)assert.deepEqual(projected[i],expected[i%32].result);return {format:1,actor:'node',workload:name,rounds,operations:count,warmups:3,warmupOperations:count*3,nanoseconds:elapsed.toString(),checksum:checksum(projected),inputSha256:hash,nodeSha256:lib.nodeSha,node:process.versions.node,abi:process.versions.modules,re2Runtime:lib.re2Runtime};}
const [mode,arg,...extra]=process.argv.slice(2);assert.equal(extra.length,0);
if(mode==='--write'){const dir=external(arg);assert.deepEqual(fs.readdirSync(dir),[]);const bytes=expectedBytes();fs.writeFileSync(path.join(dir,'input.json'),bytes,{flag:'wx'});const report={format:1,sourceProvenance:lib.sourceProvenance,inputSha256:sha(bytes),loaderSha256:sha(lib.read('tests/fixtures/moderation_advanced_source.cjs')),benchmarkSha256:sha(fs.readFileSync(__filename)),nodeSha256:lib.nodeSha,versions:process.versions,re2Runtime:lib.re2Runtime,sourcePins:lib.pins,transpiled:lib.compiled,provenance:lib.provenance(),poolChecksums:Object.fromEntries(names.map(n=>[n,checksum(JSON.parse(bytes).workloads[n].map(c=>c.result))]))};fs.writeFileSync(path.join(dir,'source-report.json'),JSON.stringify(report,null,2)+'\n',{flag:'wx'});console.log(JSON.stringify({inputSha256:sha(bytes)}));}
else if(mode==='--actor'){const result=actor(arg);console.log(JSON.stringify(result));}
else if(mode==='--check'){const dir=external(arg),bytes=fs.readFileSync(path.join(dir,'input.json'),'utf8');assert.equal(bytes,expectedBytes());const report=JSON.parse(fs.readFileSync(path.join(dir,'source-report.json')));assert.deepEqual(report.sourceProvenance,lib.sourceProvenance);assert.equal(report.inputSha256,sha(bytes));assert.equal(report.loaderSha256,sha(lib.read('tests/fixtures/moderation_advanced_source.cjs')));assert.equal(report.benchmarkSha256,sha(fs.readFileSync(__filename)));assert.equal(report.nodeSha256,lib.nodeSha);assert.deepEqual(report.re2Runtime,lib.re2Runtime);const data=JSON.parse(bytes);for(const name of names)assert.equal(report.poolChecksums[name],checksum(data.workloads[name].map(c=>c.result)));for(const file of fs.readdirSync(dir).filter(x=>/^sample-(node|rust)-[a-z_]+-[1-7]\.json$/.test(x))){const s=JSON.parse(fs.readFileSync(path.join(dir,file)));assert(names.includes(s.workload));assert.equal(file,`sample-${s.actor}-${s.workload}-${file.match(/-([1-7])\.json$/)[1]}.json`);assert.equal(s.inputSha256,sha(bytes));assert.equal(s.operations,s.rounds*32);assert.equal(s.warmups,3);assert.equal(s.warmupOperations,s.operations*3);assert(/^[1-9][0-9]*$/.test(s.nanoseconds));assert.equal(s.checksum,checksum(Array.from({length:s.rounds},()=>data.workloads[s.workload].map(c=>c.result)).flat()));}console.log(JSON.stringify({inputSha256:sha(bytes),checked:true}));}
else throw Error('usage: --write DIR | --check DIR | --actor WORKLOAD');
